let grade = 7

if grade >= 6 {
    print("passed")
} else {
    print("failed")
}

switch grade {
case ..<6:      print("failing")
case 6...7:     print("passing")
case let v where v >= 9: print("excellent")
default:        print("good")
}

var total = 0
for i in 1..<4 {     // 1, 2, 3
    total += i
}
print(total)         // 6

for _ in 0..<3 { print("hi") }

for c in "abc" { print(c) }

func sum(_ a: Int, with b: Int) -> Int {
    a + b            // implicit 'return': single expression
}
sum(2, with: 3)      // 5

func greet(_ name: String = "world") -> String {
    "Hello \(name)"
}
greet()              // "Hello world"
greet("Ada")         // "Hello Ada"

// Multiple return values at once, via a tuple
func minMax(_ v: [Int]) -> (min: Int, max: Int)? {
    guard let lo = v.min(), let hi = v.max() else { return nil }
    return (lo, hi)
}

